import{_ as t,o,c as l,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const k=JSON.parse('{"title":"2016-NOV-09 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2016-NOV-09 :: Ceph Performance Weekly","date":"2017-01-11T00:00:00.000Z","updated":"2017-01-12T00:00:00.000Z","tags":["Ceph","RocksDB","性能优化","分布式存储","性能测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2016-NOV-09_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2016-NOV-09_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),r={name:"posts/2017/2016-NOV-09_-_-_Ceph_Performance_Weekly.md"};function i(n,e,a,_,p,c){return o(),l("div",null,[...e[0]||(e[0]=[s("<p>本次会议主要讨论了Ceph分布式存储和RocksDB的性能优化进展。以下是会议的关键内容：</p><p><strong>一、Ceph分布式存储项目进展</strong></p><ul><li><strong>内存池调整</strong>： 部分请求正在将数据移动到Blue Store的独立内存池中，以便更好地跟踪内存使用情况。</li><li><strong>Crush锁移除</strong>： Adam提交的请求可能有助于移除Crush锁，提高性能。</li><li><strong>RocksDB优化</strong>： Dan正在进行相关工作，值得期待。</li><li><strong>Blue Store性能优化</strong>： 已合并新的Rocks TBE配置应用程序设置，使用更大的缓冲区以减少RocksDB的写入压力。</li><li><strong>并行事务提交</strong>： Blue Store的并行事务提交功能正在开发中。</li><li><strong>性能回归</strong>： 由于RocksDB编译时优化导致的性能下降已修复。</li></ul><p><strong>二、RocksDB性能测试及优化</strong></p><ul><li><strong>RocksDB与Jetta Scale对比</strong>： 进行了RocksDB和Jetta Scale的性能对比测试，发现RocksDB在非稳定状态下性能更好，但在稳定状态下性能较差。</li><li><strong>Sharding逻辑问题</strong>： 发现Sharding逻辑存在错误，导致性能下降。</li><li><strong>RocksDB优化方向</strong>： <ul><li>减少数据集大小，降低压缩频率。</li><li>优化读取操作，提高全读场景下的性能。</li><li>考虑使用更小的对象大小，减少碎片化。</li></ul></li></ul><p><strong>三、后续行动计划</strong></p><ul><li>继续进行RocksDB与Jetta Scale的性能对比测试，包括多OST和全读场景。</li><li>修复Sharding逻辑错误。</li><li>优化RocksDB的读取操作和对象大小设置。</li><li>探索其他RocksDB优化方案。</li></ul><p><strong>四、其他事项</strong></p><ul><li>预计将在今年内尝试使用RDMA进行数据同步。</li><li>邀请其他团队成员分享性能测试数据。</li></ul><p>本次会议内容涵盖了内存池调整、Sharding逻辑问题、RocksDB优化等多个方面，为Ceph项目的进一步发展奠定了基础。</p>",10)])])}const d=t(r,[["render",i]]);export{k as __pageData,d as default};
